# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check SELECT query
if not any('SELECT' in line.upper() and 'name' in line.lower() and 'price' in line.lower() and 'FROM' in line.upper() for line in lines if 'select_sql' in line):
    raise AssertionError('Task 1: select_sql should be a SELECT query for name and price')

# Task 2: Check fetchall
if not any('.fetchall()' in line for line in lines):
    raise AssertionError('Task 2: Should use cursor.fetchall()')
if not any('all_products' in line and 'fetchall()' in line for line in lines):
    raise AssertionError('Task 2: all_products should be assigned from fetchall()')

# Task 3: Check loop and printing (flexible — accepts both unpacking and indexing)
if not any('for' in line and 'all_products' in line for line in lines):
    raise AssertionError('Task 3: Should loop through all_products')
if not any(('print' in line and ('name' in line or 'product[' in line)) for line in lines):
    raise AssertionError('Task 3: Should print product details inside the loop')

print('TEST_PASSED')
